parameters.functionCode:
const marche = items[0].json;
const client = items[1].json;

const checklist = [
  {id: 'RCCM', label: 'Registre Commerce (RCCM) valide', required: true, autoCheck: true},
  {id: 'IFU', label: 'Identifiant Fiscal Unique (IFU)', required: true, autoCheck: true},
  {id: 'CNPS', label: 'Attestation CNPS à jour (< 3 mois)', required: true, autoCheck: true},
  {id: 'IMPOTS', label: 'Attestation Fiscale (IRPP/IUTS/TVA) à jour', required: true, autoCheck: true},
  {id: 'LICENCE', label: 'Licence/Patente en cours de validité', required: true, autoCheck: true},
  {id: 'ASSURANCE', label: 'Attestation Assurance Responsabilité Civile', required: true, autoCheck: false},
  {id: 'CAPACITE_TECH', label: 'Références techniques similaires (3 ans)', required: true, autoCheck: false},
  {id: 'CAPACITE_FIN', label: 'Capacité financière (CA 3 ans, attestation banque)', required: true, autoCheck: false},
  {id: 'PERSONNEL', label: 'Personnel clé CV + diplômes', required: false, autoCheck: false},
  {id: 'MATERIEL', label: 'Matériel/Équipements disponibles', required: false, autoCheck: false},
  {id: 'SOUS_TRAIT', label: 'Sous-traitants identifiés + accords', required: false, autoCheck: false},
  {id: 'GARANTIE_SOUM', label: 'Caution de soumission (0.5-1% montant)', required: true, autoCheck: false},
  {id: 'GARANTIE_EXEC', label: 'Capacité caution bonne exécution (5-10%)', required: true, autoCheck: false},
  {id: 'RETENUE_GAR', label: 'Acceptation retenue garantie (5-10%)', required: true, autoCheck: false},
  {id: 'DELAI', label: 'Délai d\'exécution réaliste vs planning', required: true, autoCheck: false},
  {id: 'MARGE', label: 'Marge nette cible > 15% après tous coûts', required: true, autoCheck: false}
];

// Auto-check ce qu'on peut via données client
checklist.forEach(c => {
  if (c.autoCheck && client[c.id.toLowerCase()]) {
    c.status = 'ok';
    c.evidence = client[c.id.toLowerCase()];
  } else {
    c.status = 'pending';
  }
});

const completionRate = checklist.filter(c => c.status === 'ok').length / checklist.length * 100;
const criticalMissing = checklist.filter(c => c.required && c.status === 'pending').length;

let decision = 'GO';
let decisionReason = '';
if (criticalMissing > 3) { decision = 'NO-GO'; decisionReason = `${criticalMissing} pièces critiques manquantes`; }
else if (completionRate < 60) { decision = 'CONDITIONNEL'; decisionReason = `Taux complétude ${completionRate.toFixed(0)}%`; }
else if (marche.parsedAmount > client.maxCapacity) { decision = 'CONDITIONNEL'; decisionReason = `Montant > capacité financière déclarée`; }

return [{
  json: {
    marche,
    client,
    checklist,
    completionRate,
    criticalMissing,
    decision,
    decisionReason,
    qualifiedAt: new Date().toISOString()
  }
}];

